sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================================
   MEALCARE — FOOTER WIDGET CSS
   Professional Dark Frame Theme
   ServiceNow Compatible
   HTML unchanged — same class names
   Styling only
   ========================================================= */


/* =========================================================
   1. FOOTER FOUNDATION
   ========================================================= */

.cfs-footer {
  position: relative;

  width: 100%;

  padding-top: 70px;

  color: #CBD5E1;

  font-family:
    "Segoe UI",
    Arial,
    sans-serif;

  box-sizing: border-box;

  background:
    radial-gradient(
      circle at 12% 0%,
      rgba(37, 99, 235, 0.16),
      transparent 38%
    ),
    linear-gradient(
      rgba(96, 165, 250, 0.025) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(96, 165, 250, 0.025) 1px,
      transparent 1px
    ),
    #0F172A;

  background-size:
    auto,
    48px 48px,
    48px 48px,
    auto;
}


/* =========================================================
   2. TOP ACCENT LINE
   ========================================================= */

.cfs-footer::before {
  content: "";

  position: absolute;

  left: 0;
  right: 0;
  top: 0;

  height: 3px;

  background:
    linear-gradient(
      90deg,
      transparent,
      #2563EB 30%,
      #60A5FA 70%,
      transparent
    );

  pointer-events: none;
}


/* =========================================================
   3. BOX SIZING
   ========================================================= */

.cfs-footer *,
.cfs-footer *::before,
.cfs-footer *::after {
  box-sizing: border-box;
}


/* =========================================================
   4. FOOTER CONTAINER
   ========================================================= */

.cfs-footer .footer-container {
  width: 100%;

  max-width: 1180px;

  margin: 0 auto;

  padding:
    0 28px 56px;

  display: grid;

  grid-template-columns:
    2fr 1fr 1fr;

  gap: 60px;
}


/* =========================================================
   5. FOOTER BRAND
   ========================================================= */

.cfs-footer .footer-brand {
  max-width: 380px;
}


/* =========================================================
   6. FOOTER LOGO
   ========================================================= */

.cfs-footer .footer-logo {
  display: inline-flex;

  align-items: center;

  gap: 12px;

  margin-bottom: 18px;

  color: #FFFFFF;

  font-size: 24px;

  font-weight: 800;

  letter-spacing: -0.7px;

  transition:
    transform 0.25s ease;
}

.cfs-footer .footer-logo:hover {
  transform:
    translateX(3px);
}


/* =========================================================
   7. FOOTER LOGO ICON
   ========================================================= */

.cfs-footer .footer-logo-icon {
  width: 44px;
  height: 44px;

  display: flex;

  align-items: center;
  justify-content: center;

  background:
    linear-gradient(
      145deg,
      #60A5FA,
      #2563EB
    );

  color: #FFFFFF;

  border-radius: 12px;

  box-shadow:
    0 8px 20px rgba(37, 99, 235, 0.28);

  font-size: 21px;
}


/* =========================================================
   8. FOOTER DESCRIPTION
   ========================================================= */

.cfs-footer .footer-brand p {
  margin: 0;

  color: #94A3B8;

  font-size: 14px;

  line-height: 1.8;
}


/* =========================================================
   9. FOOTER COLUMNS
   ========================================================= */

.cfs-footer .footer-column {
  display: flex;

  flex-direction: column;

  align-items: flex-start;

  gap: 11px;
}


/* =========================================================
   10. COLUMN HEADINGS
   ========================================================= */

.cfs-footer .footer-column h4 {
  position: relative;

  margin: 0 0 10px;

  padding-bottom: 12px;

  color: #FFFFFF;

  font-size: 15px;

  font-weight: 800;
}


/* =========================================================
   11. COLUMN HEADING ACCENT
   ========================================================= */

.cfs-footer .footer-column h4::after {
  content: "";

  position: absolute;

  left: 0;
  bottom: 0;

  width: 32px;
  height: 3px;

  background:
    linear-gradient(
      90deg,
      #2563EB,
      #60A5FA
    );

  border-radius: 99px;
}


/* =========================================================
   12. FOOTER LINKS
   ========================================================= */

.cfs-footer .footer-column a {
  position: relative;

  color: #94A3B8;

  font-size: 14px;

  text-decoration: none;

  transition:
    color 0.2s ease,
    transform 0.2s ease;
}


/* =========================================================
   13. FOOTER LINK HOVER
   ========================================================= */

.cfs-footer .footer-column a:hover {
  color: #60A5FA;

  transform:
    translateX(4px);
}


/* =========================================================
   14. LINK UNDERLINE
   ========================================================= */

.cfs-footer .footer-column a::after {
  content: "";

  position: absolute;

  left: 0;
  bottom: -3px;

  width: 100%;
  height: 1px;

  background: #2563EB;

  transform:
    scaleX(0);

  transform-origin: left;

  transition:
    transform 0.25s ease;
}

.cfs-footer .footer-column a:hover::after {
  transform:
    scaleX(1);
}


/* =========================================================
   15. FOOTER BOTTOM
   ========================================================= */

.cfs-footer .footer-bottom {
  width: 100%;

  min-height: 62px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  padding:
    0 max(
      28px,
      calc((100% - 1180px) / 2)
    );

  background:
    rgba(2, 6, 23, 0.55);

  border-top:
    1px solid #1E293B;

  color: #94A3B8;

  font-size: 12px;
}


/* =========================================================
   16. FOOTER BOTTOM TEXT
   ========================================================= */

.cfs-footer .footer-bottom span {
  max-width: 1180px;
}


/* =========================================================
   17. ACCESSIBILITY
   ========================================================= */

.cfs-footer a:focus-visible {
  outline:
    2px solid #60A5FA;

  outline-offset:
    4px;

  border-radius:
    4px;
}


/* =========================================================
   18. LARGE TABLET / SMALL DESKTOP
   ========================================================= */

@media (min-width: 992px) and (max-width: 1199px) {

  .cfs-footer .footer-container {
    max-width: 1100px;

    gap: 40px;
  }
}


/* =========================================================
   19. TABLET
   ========================================================= */

@media (min-width: 768px) and (max-width: 991px) {

  .cfs-footer .footer-container {
    padding-left: 24px;
    padding-right: 24px;

    grid-template-columns:
      2fr 1fr 1fr;

    gap: 30px;
  }
}


/* =========================================================
   20. SMALL TABLET
   ========================================================= */

@media (min-width: 576px) and (max-width: 767px) {

  .cfs-footer .footer-container {
    padding-left: 22px;
    padding-right: 22px;

    grid-template-columns:
      1fr 1fr;

    gap: 40px;
  }

  .cfs-footer .footer-brand {
    grid-column:
      1 / -1;

    max-width: 100%;
  }

  .cfs-footer .footer-bottom {
    min-height: auto;

    padding:
      18px 22px;

    flex-direction: column;

    align-items: flex-start;

    gap: 6px;
  }
}


/* =========================================================
   21. MOBILE
   ========================================================= */

@media (max-width: 575px) {

  .cfs-footer {
    padding-top: 50px;
  }

  .cfs-footer .footer-container {
    padding:
      0 18px 38px;

    grid-template-columns:
      1fr;

    gap: 36px;
  }

  .cfs-footer .footer-brand {
    max-width: 100%;
  }

  .cfs-footer .footer-bottom {
    min-height: auto;

    padding:
      17px 18px;

    flex-direction: column;

    align-items: flex-start;

    gap: 6px;
  }
}


/* =========================================================
   22. SMALL MOBILE
   ========================================================= */

@media (max-width: 399px) {

  .cfs-footer .footer-container {
    padding-left: 15px;
    padding-right: 15px;
  }

  .cfs-footer .footer-bottom {
    padding-left: 15px;
    padding-right: 15px;
  }
}


/* =========================================================
   23. REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .cfs-footer *,
  .cfs-footer *::before,
  .cfs-footer *::after {
    animation: none !important;

    transition: none !important;
  }
}
